	[1418] = {
		name = "荒蕪之地",
		short = "荒蕪之地是一片龜裂的荒漠，遍布乾土、散落的巨石與蜿蜒的峽谷，四面八方都被群山環繞。這裡除了郊狼、美洲獅與禿鷹之外，幾乎沒有什麼生物能夠存活。",
		full = "荒蕪之地是一片龜裂的荒漠，遍布乾土、散落的巨石與蜿蜒的峽谷，四面八方都被群山環繞。這裡除了郊狼、美洲獅與禿鷹之外，幾乎沒有什麼生物能夠存活。\n\n北部坐落著奧達曼的遺跡，那是遠古土靈的造物。它被發掘出來時，首次揭示了矮人崇高起源的線索，鐵爐堡的探勘者蜂擁而至，在遺跡中搜尋泰坦的古物。然而沉睡了數千年的石窟穴居人甦醒過來，屠殺了探險者，如今正以野蠻的決心守護著他們竊據的城市。奧達曼南方不遠處矗立著一座巨大的黑鐵要塞，那裡的矮人與塵吼巨魔以及東方和黑龍後裔一同築巢的飛龍征戰不休。\n\n後來，卡加斯在此建立，成為部落在卡茲莫丹唯一的前哨，以便獸人監視他們叛離的黑石族人。大酋長索爾親自派遣卡加斯遠征軍，追捕雷德·黑手。",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
