	[1419] = {
		name = "詛咒之地",
		short = "詛咒之地名副其實。腳下的紅色黏土曾是黃褐色的土地，屬於一片名為黑色沼澤的陰暗濕地，直到獸人部落在此撕開黑暗之門，大舉湧入艾澤拉斯。",
		full = "詛咒之地名副其實。腳下的紅色黏土曾是黃褐色的土地，屬於一片名為黑色沼澤的陰暗濕地，直到獸人部落在此撕開黑暗之門，大舉湧入艾澤拉斯。那一天滲漏而出的魔法將土壤燒成赤紅，也讓它永遠失去了生機。如今這裡除了耐旱的荒漠灌木之外寸草不生，只有同樣頑強的荒漠生物：蜥蜴、蠍子與土狼。\n\n大法師卡德加與祈倫托建立了守望堡，以監視這座門戶的廢墟，確保再也沒有任何東西從中通過。和平維持了兩年，直到德拉諾的部落重新開啟黑暗之門並圍攻這座要塞。當耐祖奧的儀式開始撕裂德拉諾時，卡德加與其他法師利用古爾丹之顱，從另一端將黑暗之門的石框炸成碎片，徹底切斷了兩個世界之間的橋梁。\n\n如今，守望堡的法師與聖騎士仍嚴峻地監守著這座死寂的黑暗之門。這是一個緊密而不苟言笑的團體，不信任任何人，也不寬恕任何疏失；在這片來自東海的暴雨還來不及帶來任何好處、便已從焦硬地面流走的土地上，這裡是唯一的庇護之所。",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "提里斯法林地",
		short = "多年來，提里斯法林地的天空始終籠罩著病態的綠光，樹木緊抓著瘟疫所留下的最後一絲生機。",
		full = "多年來，提里斯法林地的天空始終籠罩著病態的綠光，樹木緊抓著瘟疫所留下的最後一絲生機。這裡曾是泰瑞納斯國王治下寧靜的農莊，世世代代的人們在磨坊與南瓜田間安穩度日。直到阿薩斯·米奈希爾洗劫羅德隆，讓瘟疫席捲整片鄉野，殺害了這裡的人民，再將他們喚起成為巫妖王的奴僕，一切便宣告終結。至今仍有萬人塚標示著那些因死者過多而無法妥善安葬的地方。數月之後，就在巴尼爾農場附近，希瓦娜斯·風行者率領她的女妖反抗阿薩斯，向這名死亡騎士射出一支毒箭，隨後才被科爾蘇加德的骷髏大軍擊退。\n\n從那片廢墟中誕生了被遺忘者，也就是希瓦娜斯麾下擁有自由意志的亡者，他們將這片土地據為己有。然而他們的敵人從未離開：血色十字軍盤據著北方古老的血色修道院，這群狂熱分子焚燒並獵殺一切非人類的存在。",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "銀松森林",
		short = "銀松森林，或簡稱銀松，是一片廣闊的古老森林，沿著羅德隆崎嶇的西部海岸延伸。這裡的地勢從平坦到丘陵起伏不等，四周環繞著更加高聳的山脈。",
		full = "銀松森林，或簡稱銀松，是一片廣闊的古老森林，沿著羅德隆崎嶇的西部海岸延伸。這裡的地勢從平坦到丘陵起伏不等，四周環繞著更加高聳的山脈。森林靜得詭異，只有偶爾在林間迴盪的異樣嚎叫打破沉寂。長滿青苔的岩簷在寒風中顫抖，樹木全都病懨懨的或正在枯死。破敗的農莊與廢棄的礦坑散布各處，如今成了林中更為黑暗之物的巢穴。\n\n這片林地陰森而荒野，高大的銀色樹皮松樹聳立在長滿青草的小丘之上。當銀松森林還蒼翠而充滿生機時，曾受聯盟守護。如今這裡卻籠罩在鬼魅般的迷霧之中。被遺忘者控制著森林北部，並不斷與卑劣的腐皮豺狼人發生衝突。殘存的人類仍掌控著森林南部，但他們已陷入絕境，兵力也捉襟見肘。達拉然經常派遣遠征隊進入銀松，保護這些人民，並研究亡靈瘟疫與狼人詛咒──這種神秘的疾病會讓受害者在月亮升起時化為嗜血的狼人。\n\n吉爾尼斯與希爾斯布萊德丘陵位於森林南方，提里斯法林地則在北方。洛丹米爾湖是銀松的東側邊界。\n\n儘管這片領土屬於被遺忘者，他們的主權卻受到達拉然法師與天譴軍團爪牙的挑戰，後者已佔據了部分荒廢的田野與農莊。腐皮豺狼人以神秘的芬里斯島為據點，猛烈攻擊任何膽敢接近他們的人。西南方坐落著焚木村，村民們中了大法師阿魯高的詛咒，每到夜晚便會化為嗜血的狼人。阿魯高就住在附近影牙城堡那陰暗的高塔中。\n\n銀松森林戰事頻仍，因為來自南海鎮的聯盟部隊時常深入這片被遺棄的森林，攻打瑟伯切爾或進入影牙城堡。這裡是被遺忘者家園的邊緣，也是亡靈瘟疫對植物影響所能見到的最南端。",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "西瘟疫之地",
		short = "這裡曾是羅德隆北部最美麗的農地，森林蓊鬱，一片青翠，從安多哈爾供應王國的糧倉，並由壁爐谷的大廳治理。",
		full = "這裡曾是羅德隆北部最美麗的農地，森林蓊鬱，一片青翠，從安多哈爾供應王國的糧倉，並由壁爐谷的大廳治理。而這份繁榮，卻成了摧毀它的武器。\n\n詛咒神教依照巫妖王的計畫，以可攜式大鍋將他的瘟疫能量運往南方，把大鍋藏在忠誠信徒的村莊裡，並將最大的四座設置在安多哈爾自己的田野中。穀物本身遭到了污染，並以沒有人想到要盤查的馬車運往羅德隆各地。吃下自家麵包的人們病倒、死去，接著再度起身，成為巫妖王的奴僕。森林再也沒有復原。松樹灰白佇立，針葉枯褐，籠罩在病態的霧靄之下，樹幹上長滿了腫瘤般的贅生物。\n\n僅存的秩序是在王國崩潰後重建的：血色十字軍奪取了壁爐谷的瑪登霍爾德城堡，並以此為據點出擊，對抗盤據其餘土地的亡靈。在這一切之中，只有一處地方保有些許安寧：獻給光明使者烏瑟的烏瑟之墓，那是枯萎之力從未觸及的土地。",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "東瘟疫之地",
		short = "這片土地曾是農田，東部林野的村莊散落在羅德隆第二大城斯坦索姆的周圍。如今那一切都已蕩然無存。",
		full = "這片土地曾是農田，東部林野的村莊散落在羅德隆第二大城斯坦索姆的周圍。如今那一切都已蕩然無存。土壤變得褐黃而病態，樹木腫脹成蕈菇，空氣中瀰漫著濃厚的橙色霧氣。\n\n阿薩斯王子正是來到斯坦索姆，追查一場早已奪走鎮民性命的瘟疫的源頭。白銀之手的領袖烏瑟大人拒絕讓他淨化這座城市。阿薩斯當場解除了他的指揮權，解散了白銀之手，並親手將斯坦索姆的人民斬殺殆盡，不讓他們化為天譴軍團的爪牙。他並未就此罷手──他追擊恐懼魔王瑪爾加尼斯直到北方，歸來時已成為死亡騎士，並弒殺了自己的父親，終結了羅德隆王國。\n\n亞歷山德羅斯·莫格萊尼以白銀之手的殘部組建了一支十字軍，意圖收復這片廢墟，奪下了提爾之手與半座斯坦索姆；然而他的死讓他的騎士團分裂為銀色黎明與血色十字軍，後者至今仍佔據著這片原野，與天譴軍團無休止地征戰，不歡迎任何外人。",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "希爾斯布萊德丘陵",
		short = "希爾斯布萊德土壤肥沃，丘陵青翠，旅人們說，這就是瘟疫來臨之前整個羅德隆的模樣。",
		full = "希爾斯布萊德土壤肥沃，丘陵青翠，旅人們說，這就是瘟疫來臨之前整個羅德隆的模樣。這既是它的慰藉，也是它的殘酷：這片土地記得其他地方早已失去的一切，而守護這裡的人們，卻仍在打著那場毀掉其餘土地的戰爭。\n\n第二次大戰之初，獸人襲擊者突襲了這裡的沿海城鎮，奧格林·末日錘更親自率軍進攻敦霍爾德城堡，將祖爾金從牢房中救出。數十年後，來到這片丘陵的是索爾，他召集四散的獸人氏族，趁夜潛入南海鎮奪取船隻，載著新部落渡海前往卡林多。\n\n獸人所開啟的一切，由被遺忘者延續了下去。他們佔領塔倫米爾，作為自己最南端的據點，並將其化為對抗南海鎮與希爾斯布萊德農場人類的前線基地，而這些人類始終堅定地效忠聯盟。\n\n如今松林點綴著農田，道路依舊穿越牧場，通往北方陰鬱的被遺忘者聚落，彷彿這片土地本身仍在等待，看看最終會由哪一方擁有它。",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "辛特蘭",
		short = "三錘之戰後，蠻錘矮人離開了格瑞姆巴托的隧道，向北遷徙，在鷹巢山的地面上建立了家園。",
		full = "三錘之戰後，蠻錘矮人離開了格瑞姆巴托的隧道，向北遷徙，在鷹巢山的地面上建立了家園。他們捨棄了岩石與熔爐，轉而擁抱天空與羽翼，與當地的野生獅鷲獸緊密結盟，甚至在自己的城市中豎立一座巨大的獅鷲石像，以紀念這份羈絆。早已佔據這片土地的森林食人妖，是昔日強盛的阿曼尼帝國的殘餘，他們將矮人視為侵佔祖先土地的外來者，一有機會便襲擊鷹巢。\n\n第二次大戰期間部落席捲而來時，庫德蘭·蠻錘族長與他的騎士們在此之前甚至不知道有這樣的入侵者存在，他們揮舞著蘊含風暴之力的戰錘從天而降，猛攻獸人的行軍隊伍，毫不停歇地追擊。奧格林·末日錘原本希望將聯盟的主力引入辛特蘭，好讓他得以毫無阻礙地進攻奎爾薩拉斯，然而安度因·洛薩識破了這個計畫，親自趕到庫德蘭身邊，兩人聯手擊潰了入侵者，並將他們趕回奧特蘭克山脈。為此，庫德蘭承諾他的族人將援助聯盟。",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "丹莫洛",
		short = "丹莫洛積雪深厚，四面都被卡茲莫丹的群山環繞，隘口始終有矮人部隊看守。",
		full = "丹莫洛積雪深厚，四面都被卡茲莫丹的群山環繞，隘口始終有矮人部隊看守。在這片山脈屬於其他任何人之前，它屬於霜鬃冰食人妖；他們在遠古時代脫離德拉克瑞帝國之後，便在此地定居。\n\n直到第一批地精從奧達曼中爬出，運用他們的智慧抵禦嚴寒與食人妖，在山峰深處挖掘出堅固的居所，一切才有了改變。五百年後，矮人也跟隨他們的腳步走出奧達曼，被他們曾在地平線上瞥見的同一片山脈所吸引，並在其中最高的山峰下建立了鐵爐堡。發現地精早已在附近定居後，兩個種族締結了一份從未破裂的友誼：矮人出力協助建造諾姆瑞根，地精則分享他們機械的奧秘。他們的軍隊聯手擊潰了霜鬃食人妖，將倖存者趕回丘陵之中，徹底終結了食人妖對這片土地的統治。\n\n如今諾姆瑞根已經淪陷、化為廢墟，它的人民擠進鐵爐堡尋求庇護。",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "灼熱峽谷",
		short = "這裡曾是一片青翠的土地，屬於赤脊山的一部分，直到兩百三十多年前，大地本身被撕裂開來。",
		full = "這裡曾是一片青翠的土地，屬於赤脊山的一部分，直到兩百三十多年前，大地本身被撕裂開來。\n\n三錘之戰中，黑鐵矮人的術士領主索瑞森尋求一件足以擊垮敵人的武器。他與七名最信任的矮人探入世界深處，召喚了本該永遠沉睡的力量。回應他們的並非僕從，而是主宰：遠古的炎魔之王拉格納羅斯。他的甦醒讓黑石山從大地中拔地而起，方圓數哩的土地盡成焦黑，黑鐵矮人的首都索瑞森也被壓成瓦礫。南方焦灼的草原從此被稱為燃燒平原；北方這座飽受摧殘的山谷，則成了灼熱峽谷。\n\n浩劫之後，並非所有黑鐵矮人都對他們的氏族保持忠誠。其中一些人脫離了族群，自稱瑟銀兄弟會，並在俯瞰谷底的位置建立了瑟銀哨塔，下方正是他們昔日族人在谷底開鑿出的巨大礦坑，他們就在高處監視著黑鐵矮人的勞作。",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "燃燒平原",
		short = "燃燒平原上空的紅光從未消褪，黑石山不時噴發的火光將它映亮，而大地也從未冷卻。",
		full = "燃燒平原上空的紅光從未消褪，黑石山不時噴發的火光將它映亮，而大地也從未冷卻。黑暗之門開啟的兩百年前，黑鐵矮人遭鐵爐堡放逐，來到了這裡。他們的術士領主索瑞森企圖召喚元素僕從，以贏得對抗銅鬚與蠻錘氏族的三錘之戰。然而回應他的並非僕從，而是曾遭泰坦放逐的炎魔之王拉格納羅斯。他的降臨熔化了周圍的山脈，在爆炸的中心隆起一座火山，也毀滅了召喚他的矮人。這座新山峰以北成了灼熱峽谷；以南則成了燃燒平原，從此滿目瘡痍。\n\n第一次大戰期間，獸人定居在火山的山坡上，並在第二次大戰中一直以黑石塔作為據點。戰後黑石獸人重返此地，至今仍盤據於此，遵循著索爾停戰之前那套殘暴的古老方式。奈法利安麾下的黑龍佔據著塔的上層，據說拉格納羅斯仍在這一切之下的某處蟄伏醞釀。",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "艾爾文森林",
		short = "第一次大戰中獸人來襲時，成千上萬的獸人行軍穿越艾爾文森林，包圍了暴風城，使它除了大海之外與外界完全隔絕。",
		full = "第一次大戰中獸人來襲時，成千上萬的獸人行軍穿越艾爾文森林，包圍了暴風城，使它除了大海之外與外界完全隔絕。騎士冠軍安度因·洛薩率領暴風城騎士直接穿越森林衝鋒，出其不意地襲擊獸人的後衛，將他們擊潰四散。這為城市爭取了時間，卻仍然不夠。大酋長黑手很快便攻下閃金鎮與月溪鎮，這兩座城鎮是部落與國王之間最後的屏障，隨後暴風城堡也慘遭洗劫。洛薩帶領倖存者出海，前往羅德隆，而這座城市的廢墟一度落入風暴掠奪者氏族手中。至今仍有零星的獸人投石車殘骸破損腐朽地散落在這片地區，是那段佔領時期僅存的遺跡。\n\n城東的北郡農場曾是暴風城農民的驕傲。石匠公會花了數年重建這座化為廢墟的首都，卻始終未獲報酬；貴族們寧可解散公會，也不願償還這筆債務。會長艾德溫·范克里夫的憤怒蔓延成暴動，奪走了蒂芬·艾莉莉安·烏瑞恩王后的性命，也催生了迪菲亞兄弟會。兄弟會將農民逐出北郡，佔據了那裡的田地。",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "逆風小徑",
		short = "逆風小徑貫穿艾澤拉斯中部的群山，連接暮色森林與悲傷沼澤。二十年前，這裡還被視為赤脊山的一部分。",
		full = "逆風小徑貫穿艾澤拉斯中部的群山，連接暮色森林與悲傷沼澤。二十年前，這裡還被視為赤脊山的一部分。\n\n卡拉贊象牙塔曾是黑暗法師麥迪文的權力之座，它矗立在這片嶙峋地帶的中央，不斷將邪惡的魔法滲入大地。樹木已石化凋零，一陣可怕的狂風在峽谷間淒厲呼嘯。巨魔、惡魔、亡靈與少數人類吉普賽人在內陸遊蕩──傳言還說，一股新的勢力已佔據了象牙塔，巨魔與惡魔都受其掌控。",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "暮色森林",
		short = "一層不自然的夜幕籠罩著暮色森林，從未散去。",
		full = "一層不自然的夜幕籠罩著暮色森林，從未散去。這裡曾是艾爾文森林中一片美麗的林地，如今卻成了受詛咒、逐漸死去的土地：樹木在黑霧中長得扭曲糾結，死者從墳墓中爬起，狼人也隨著黑暗本身悄悄潛入，受到月神之鐮的力量所吸引。從逆風小徑進逼而來的巨魔，更讓這裡的苦難雪上加霜。\n\n暴風城的庇護在這裡早已名存實亡，留下來的人們也學會了不靠它守住自己的家園。他們的民兵組織守夜人巡邏道路，守護夜色鎮，抵禦任何在陰影中出沒的東西──骷髏戰士與食屍鬼、兇猛的狼人，還有迪菲亞的人馬。\n\n森林的中心是一座早已死寂的火山口，籠罩在比周圍的黑暗更為柔和的暮光之中。那裡矗立著一棵巨樹，樹根伸向翡翠夢境，沉睡德魯伊的力量影響著附近生長的一切。更遠處則是荒廢的農莊，以及廣闊的烏鴉嶺墓園，自黑暗降臨以來，墓園年復一年地被填滿。",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "洛克莫丹",
		short = "洛克莫丹的湖水安臥在灰色的岩石之間，由巨石水壩攔蓄。這座矮人工程的傑作，艾澤拉斯上沒有任何建築能與之匹敵。",
		full = "洛克莫丹的湖水安臥在灰色的岩石之間，由巨石水壩攔蓄。這座矮人工程的傑作，艾澤拉斯上沒有任何建築能與之匹敵。群山在四面陡然聳起，稀疏地長著松樹與樺樹，湖泊本身則靜謐無聲，彷彿從未受過任何驚擾。\n\n這座湖泊曾是一片戰場。第二次大戰中，部落的獸人席捲這片地區，在此與聯盟決一死戰。鐵爐堡守住了。矮人擊退了獸人，奪回了洛克莫丹，而那場戰爭留下的殘骸卻從未被徹底清理：損毀的投石車與破碎的弩砲至今仍半沉在湖床與湖中島嶼上，是這片平靜水域曾為殺戮之地的唯一證據。",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "赤脊山",
		short = "赤脊山位於艾爾文森林以東、暮色森林東北方，以及燃燒平原以南。",
		full = "赤脊山位於艾爾文森林以東、暮色森林東北方，以及燃燒平原以南。\n\n赤脊山是一片田園詩般的土地，河水奔流，榆樹高聳，地勢逐漸攀升。它受暴風城保護，但自第二次大戰以來，名義上一直是獨立的。這裡仍是艾澤拉斯最後幾處和平的地區之一，居民安穩知足，為暴風城供應木材、漁獲與農作物。然而這份和平並不完美：一支來自燃燒平原的黑石獸人部隊佔據了石堡要塞，儘管到目前為止他們還算安分。與西部荒野的殘破相比，赤脊山依然維持著完整。\n\n止水湖北岸坐落著湖畔鎮，飽受周圍山丘中的豺狼人與黑石獸人圍攻。在它南方，名為三角路口的十字路口將湖畔鎮與艾爾文森林和暮色森林相連，並經由湖邊大道通往石堡要塞，而這條路上盤據著雛龍、豺狼人、魚人與野獸。\n\n湖面看起來頗為平靜，但魚人潛伏在水下，而湖底有海怪的傳聞也始終流傳不息。",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "荊棘谷",
		short = "荊棘谷是暮色森林以南的一片廣袤叢林。叢林食人妖在這片悶熱的雨林中巡邏，納迦沿著海岸獵食，而荊棘藤蔓與野獸讓旅途危機四伏。",
		full = "荊棘谷是暮色森林以南的一片廣袤叢林。叢林食人妖在這片悶熱的雨林中巡邏，納迦沿著海岸獵食，而荊棘藤蔓與野獸讓旅途危機四伏。\n\n這座山谷曾是古拉巴什帝國的心臟，帝國的偉大城市遍布整個地區。帝國衰亡之後，這些城市崩塌成廢墟，但仍有食人妖居住其中。位於東北方的祖爾格拉布，曾是古拉巴什的首都。\n\n藏寶海灣原本是人類定居的小港鎮，直到被食人妖攻佔。後來熱砂企業的哥布林將食人妖逐出海灣，將這裡據為己有，並把它建設成他們在東部王國的營運中心。\n\n北方矗立著一座由庫爾森上校的遠征隊所建立的營地。在那裡，上校的心智被一名巨魔法師麥佐斯奪取，他利用一件名為心靈之眼的神器扭曲庫爾森的意志，並指揮他的部下。庫爾森的一些士兵反抗了這位被附身的指揮官，逃往西方，建立了一座營地與他對抗。",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "悲傷沼澤",
		short = "在沼澤的黑水之下，沉睡著一座比為此地命名的悲傷更加古老的神廟。",
		full = "在沼澤的黑水之下，沉睡著一座比為此地命名的悲傷更加古老的神廟。古拉巴什帝國衰亡時，一支名為阿塔萊的叛逆食人妖逃進沼澤，建立了阿塔哈卡神廟，在那裡舉行駭人的儀式，企圖將他們的黑暗洛阿神──奪魂者哈卡召喚回這個世界。他們的魔法扭曲了神廟周圍的植物與野獸，直到這股腐化再也無法被忽視。夢境之主伊瑟拉得知了這個教派的野心，便以她的力量對付他們，在哈卡歸來之前將神廟淹沒在最大的泥沼之下。但她並不相信食人妖會永遠放棄他們的神。她派遣她的伴侶伊蘭尼庫斯與一群綠龍永遠看守這座廢墟，好讓它再也無法被用來將如此邪惡釋放到世上。至今仍有綠龍族人奉她之命在這片沼澤中巡邏，而沉沒的神廟依舊被封印在水下，受到看守，卻未被摧毀。",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "西部荒野",
		short = "如今風毫無阻礙地吹過西部荒野的田野，因為這裡已沒有任何高聳之物能將它擋下。這裡曾是暴風城的糧倉，世世代代養育著這個年輕的王國。",
		full = "如今風毫無阻礙地吹過西部荒野的田野，因為這裡已沒有任何高聳之物能將它擋下。這裡曾是暴風城的糧倉，世世代代養育著這個年輕的王國。\n\n第二次大戰後，石匠公會重建了暴風城卻未獲報酬，衛兵還轉而鎮壓他們的抗議，會長艾德溫·范克里夫於是帶著手下躲進鄉間，不願接受瓦里安國王的審判。他們在那裡成了迪菲亞兄弟會。在月溪鎮一座穀倉的下方，范克里夫發現了一處古老的礦坑網絡，深得足以掩藏一件武器的建造工程，這件武器的目的是從海上焚毀暴風城。他趕走農民，僱用河爪豺狼人把守這片土地，並讓手下焚燒田地、在土中撒鹽，讓這裡再也長不出任何東西。\n\n國庫已然耗盡的暴風城，任由西部荒野自生自滅。只有格里安·斯托曼挺身而出，在沒有任何軍隊前來之際，於哨兵嶺組建了西部荒野人民軍。\n\n被撒了鹽的田地並未原諒西部荒野。昔日麥穗高及肩頭的地方，如今只長著枯黃稀疏的野草。",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "濕地",
		short = "水壩下方是一片寒冷灰暗的沼澤，河流與池塘上瀰漫著霧氣，三面被群山環繞，西面則向大海敞開。",
		full = "水壩下方是一片寒冷灰暗的沼澤，河流與池塘上瀰漫著霧氣，三面被群山環繞，西面則向大海敞開。瓦礫散落其間，那是昔日守衛這片土地的矮人要塞的殘骸。如今這裡被魚人、野獸與叛逆的獸人佔據，米奈希爾港是聯盟在此唯一真正的立足點。\n\n那座港口並非一直屬於聯盟。第二次大戰爆發時，奧格林·末日錘在巴拉丁海灣的一座小島上建造他的入侵艦隊，好讓他的船隻能繞過羅德隆的地面防線，直接襲擊其海岸。濕地為此付出了代價：獸人與巨龍大肆掠食這片土地，獵物日漸稀少。戰後港口得以重建，並為了紀念泰瑞納斯·米奈希爾二世而更名為米奈希爾港。\n\n格瑞姆巴托的陷落隨之而來。被奴役在那裡為龍喉氏族效力的紅龍軍團，一獲自由便反噬了囚禁他們的人，龍喉氏族因此瓦解，倖存者四散於荒野之中。雅立史卓莎認為封鎖這座山是她的龍族應負的責任，此後紅龍族人便一直在此看守。",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "泰達希爾",
		short = "當瑪法里恩·怒風消失於翡翠夢境之中，大德魯伊范達爾·鹿盔崛起，代替他領導塞納里奧議會，並說服了先祖議會：培育一棵新的世界之樹、贏回夜精靈失去的永生的時刻已經到來。",
		full = "當瑪法里恩·怒風消失於翡翠夢境之中，大德魯伊范達爾·鹿盔崛起，代替他領導塞納里奧議會，並說服了先祖議會：培育一棵新的世界之樹、贏回夜精靈失去的永生的時刻已經到來。他們在迷霧之海中種下了泰達希爾──大地之冠，並在它的枝幹間建造了達納蘇斯。然而曾經祝福第一棵世界之樹的諾茲多姆卻拒絕祝福這一棵，斥責這個願望傲慢自大，而夜精靈所追求的永生也始終沒有到來。\n\n久而久之，泰達希爾頂端的土地籠罩在一股邪惡的氣息之下。森林中的熊怪與格雷爾陷入瘋狂，薩特出現在林間，而昔日在巨樹周圍水域中悠游的巨龜與鞭尾魚紛紛逃離，擱淺在黑海岸的岸邊死去。這股腐化的源頭至今仍是個謎，而瑪法里恩也未曾從夢境中歸來追查它。",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "黑海岸",
		short = "這片海岸大多時候都籠罩在灰色的霧氣之中，夜精靈長久以來都將其視為一種警示。",
		full = "這片海岸大多時候都籠罩在灰色的霧氣之中，夜精靈長久以來都將其視為一種警示。雨水與岩石使這片土地難以親近，除了奧伯丁這座貿易站之外，每一次在此定居的嘗試都以失敗告終。\n\n一萬年前，亞米薩蘭與巴莎蘭這兩座雙子城矗立於此，由亞斯瑞克斯·納拉辛統治。當先祖之戰讓世界破碎、大崩裂隨之降臨時，亞斯瑞克斯向他的子民發誓，他一定會拯救他們。他遵守了承諾的字面，卻背棄了它的本意：他將子民的靈魂封入靈魂寶石，告訴他們這就是永生，實際上卻是抽取他們來餵養自己的力量。這些城市淪為廢墟，而如今在那些石頭間行走的，並非全都得到了安息。\n\n第三次大戰之後，范達爾·鹿盔帶著塞納里奧議會的德魯伊來到黑海岸，在這片海岸上種下了一棵新的世界之樹──泰達希爾。",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "梣谷",
		short = "梣谷是一片古老的森林，古木參天，古老的魔法濃厚，而這裡的爭奪從未停止。",
		full = "梣谷是一片古老的森林，古木參天，古老的魔法濃厚，而這裡的爭奪從未停止。\n\n戰歌氏族的獸人最初以伐木工的身分來到這裡。尼洛克·貪指手下的哥布林大肆砍伐樹木，直到當地的熊怪將他們擊退；而葛羅姆·地獄吼又先後擊潰了熊怪與哨兵，以保住哥布林的援助。塞納留斯親自前來修復被砍伐的一切，卻為此付出了生命：燃燒軍團的主宰們將他的信任化為陷阱，葛羅姆將他擊殺。\n\n更糟的事接踵而至：燃燒軍團全面進軍梣谷。阿克蒙德的地獄火從天而降，熊熊燃燒，亡靈與惡魔從東方蜂擁而來，擊潰了夜精靈、獸人與人類各自為戰的軍隊，接著繼續向海加爾山推進。泰蘭妲·語風將瑪法里恩從翡翠夢境中喚醒，他卻發現記憶中的森林已被邪能之火與令人窒息的枯萎所吞噬。\n\n那場古老的爭奪從未結束。夜精靈依然守著阿斯特蘭納與散落各處的避難所；部落則將戰歌營地深深推進到南方與東方，砍伐木材，將哨兵步步逼退。雙方都從未為這片森林的爭奪畫下句點。",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "千針石林",
		short = "峽谷又深又乾，谷底隱沒在高聳的石柱山之間，直到東方才豁然開朗，化為閃光平原──一片廣闊天空下的巨大鹽田。",
		full = "峽谷又深又乾，谷底隱沒在高聳的石柱山之間，直到東方才豁然開朗，化為閃光平原──一片廣闊天空下的巨大鹽田。在如此荒涼的土地上，從亂風崗或黑雲峰周圍的高處眺望日出，是一幅壯麗的景象。德魯伊奎恩丁曾經懷疑，這裡的嚴酷乾旱緊鄰著菲拉斯鬱鬱蔥蔥的叢林，或許根本不是自然形成的，而是某種奇異的魔法施加於這片土地上所留下的痕跡。\n\n高聳的石柱山屬於牛頭人，亂風崗便是他們在其間的據點。他們守住這片土地並非毫無挑戰。當地的半人馬不斷進逼，更糟的是，他們自己的同族恐怖圖騰部族也倒戈相向，迫使亂風崗的牛頭人為了這片高地與同族手足相殘。直到得到部落的援助，他們才擊退了半人馬與恐怖圖騰。",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "石爪山脈",
		short = "石爪峰在屬於任何民族之前，始終屬於眾靈。",
		full = "石爪峰在屬於任何民族之前，始終屬於眾靈。夜精靈在峰頂設有一處獸穴與一片林地，在那裡與自然交流；牛頭人也將它視為聖地，因為不朽的神諭者曾在這裡注視著大地之母所編織的命運之線。傳說第一批在這片山脈定居的牛頭人，將燃燒的圖騰扛上最高的峭壁，為安榭點燃篝火，以驅散緊附在岩石上的黑暗。\n\n在山腰較低處，伊露恩很久以前曾祝福一座泉水，賦予它治癒的力量。後來鷹身人佔據了附近的山峰，捕捉在那裡築巢的雙足飛龍，並污染了泉水。索爾帶著凱恩·血蹄與他的牛頭人前來討伐她們，擊潰了一群半人馬，贏得淨化符文，淨化了被鷹身人污染的一切。重獲自由的雙足飛龍載著他們飛上了石爪峰頂。\n\n然而在南方，那份與大地之間的古老和平已不復存在。風險投資公司將狂風峭壁剝得一片光禿，砍光樹木，讓煤煙充斥空氣，以油污與廢料污染水源，直到山中的眾靈發出強烈的哀號，就連遠在奧格瑪的薩滿都能聽見。",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "淒涼之地",
		short = "石母塞拉贊恩之女瑟萊德絲，曾沉睡在一片肥沃的草原之下。",
		full = "石母塞拉贊恩之女瑟萊德絲，曾沉睡在一片肥沃的草原之下。牛頭人薩滿相信大地之母本身就居於地底，數十年來不斷向她呼喚，直到終於有某種存在回應──那不是大地之母，而是被從沉睡中驚醒、滿懷怒火的瑟萊德絲。她吞噬大地來恢復自己虛弱的形體，草原在一瞬間死去。牛頭人將殘存的土地命名為淒涼之地。\n\n森林之王塞納留斯之子札爾塔前來束縛她，卻愛上了她，而她也回應了他的愛。兩人結合生下了半人馬，而半人馬的第一個舉動，便是殺害了自己的父親。他們迅速繁衍，將牛頭人逐出這片土地，揭開了兩族之間長達數百年的戰爭。\n\n瑟萊德絲至今仍居於西部峽谷之下的瑪拉頓，半人馬也將他們種族的誕生追溯到那裡。",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "菲拉斯",
		short = "菲拉斯在鄰近的土地之間顯得格外奇特：周圍的荒原只見塵土，這裡卻是一片古木參天的雨林。",
		full = "菲拉斯在鄰近的土地之間顯得格外奇特：周圍的荒原只見塵土，這裡卻是一片古木參天的雨林。精靈的遺跡散落在這片綠意之中，一半被樹根與藤蔓吞沒，其中最宏偉的是被掩埋的城市厄運之槌。\n\n如今戈杜尼巨魔佔據了菲拉斯，而他們是藉由破壞來將它據為己有。他們砍倒了大片森林，他們帶來的污染如同疾病般籠罩這片土地。在厄運之槌的城牆之外，他們的劫掠隊在南方森林中焚燒村莊、殺害旅人；這股在荒野中蔓延的腐化，源頭可以追溯到地底的廢墟。\n\n恐怖圖騰牛頭人至今仍散居在這片地區，被那些記得這個部族所作所為的人追殺。",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "塵泥沼澤",
		short = "這裡的蚊蟲從不停歇，泥濘也是如此。",
		full = "這裡的蚊蟲從不停歇，泥濘也是如此。樹木的枝葉在水面上交織得如此濃密，陽光只能破碎地灑落；鱷魚與魚人在海水與沼澤交會的鹹水淺灘中伺機而動。在南方，黑龍聚集的數量之多，人們乾脆就稱那裡為巨龍沼澤。\n\n珍娜·普勞德摩爾在這片荒野建立了第一個真正的家園：海加爾山之役後，她帶領子民來到這裡，在多岩的島上建立了塞拉摩。她的城牆閃耀奪目，卻也將她困在其中：在通往貧瘠之地的道路上零星的檢查哨之外，沼澤依舊如往昔般荒野，而她的駐軍也因一樁樁無人能解釋的悄然逃亡而日漸稀薄。\n\n部落與聯盟之間的和平，也正是在這裡徹底破裂。海軍上將戴林·普勞德摩爾率領庫爾提拉斯艦隊在沼澤中進攻部落，隨後的衝突以他的死告終，也讓停戰協定化為公開的仇恨。\n\n蕨牆村坐落在石槌巨魔向部落敞開大門的地方。在它之外，通往貧瘠之地的道路空無一人，日漸荒廢，只有自古以來便主宰這片土地的迅猛龍與蜘蛛在一旁窺伺。",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "塔納利斯",
		short = "黃沙填滿了昔日叢林所在之地。在世界破碎之前，塔納利斯一片青綠，是古拉巴什帝國宣稱擁有的領土。",
		full = "黃沙填滿了昔日叢林所在之地。在世界破碎之前，塔納利斯一片青綠，是古拉巴什帝國宣稱擁有的領土。當大崩裂將大地撕裂時，叢林死去，殘存的一切被烤成了沙丘與岩石。一支食人妖部族在海水退去時被困在這裡，在隨後的漫長歲月裡，他們的身體與生活方式逐漸向沙漠屈服，直到他們不再是從前的食人妖，而成了沙漠食人妖──沙怒族，一個由困住他們的土地所塑造的民族。\n\n熱砂企業的哥布林選擇在這片荒原經商，建立了加基森與熱砂港，因為在卡林多所能容許他們定居的地方之中，這片沙漠最接近他們那沉沒的故鄉。熱砂港的碼頭向遠方的島嶼延伸而去，但哥布林將船隻留給自己使用，不願載運任何其他種族渡海。\n\n在沙丘與南方山脈之下，隧道綿延數哩，大多未經勘測，而那些深入其中的人，並不總能回來說出他們的發現。",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "艾薩拉",
		short = "一萬年來，秋天始終盤據著艾薩拉。樹木燃燒著橙紅的色彩，懸崖之下直落珊瑚礁，一座城市至今仍沉睡在那裡。",
		full = "一萬年來，秋天始終盤據著艾薩拉。樹木燃燒著橙紅的色彩，懸崖之下直落珊瑚礁，一座城市至今仍沉睡在那裡。艾薩拉曾是夜精靈所建立過最偉大的都城，而先祖之戰來臨時，它大半沉入了海中。少數殘破的建築仍緊附在崖壁上，俯瞰著自己沉在水下的廢墟。\n\n很久以後，伊利丹·怒風帶著他的納迦、莫古爾與薩特從海加爾山向北逃亡，途中橫掃艾薩拉的海岸，摧毀夜精靈的港口，讓任何人都無法追隨他前往薩格拉斯之墓。瑪維·影歌與她的守望者緊隨其後，剿滅他沿途留下的那些發狂的生物。",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "費伍德森林",
		short = "費伍德森林的樹木與其說是在生長，不如說是在潰爛。它們的樹皮滲出病態的膿液，葉片漆黑捲曲，樹下的野生動物也因土壤中的腐化而變得扭曲而飢渴。",
		full = "費伍德森林的樹木與其說是在生長，不如說是在潰爛。它們的樹皮滲出病態的膿液，葉片漆黑捲曲，樹下的野生動物也因土壤中的腐化而變得扭曲而飢渴。\n\n這場腐爛並非自然的意外。當燃燒軍團向海加爾山推進時，阿克蒙德下令摧毀這片森林，以削弱守衛聖山的夜精靈，恐懼魔王提克迪奧斯則以一件擁有可怕力量的術士遺物──古爾丹之顱執行了這道命令。大地的回應是由內而外地死去：古樹變得腐朽而暴戾，野獸發生突變，連土地本身都遭到了毒害。\n\n正是在這裡，伊利丹·怒風做出了決定他餘生命運的抉擇。得知這顆顱骨可以反過來對付它所造成的腐化後，伊利丹隻身進入費伍德森林，斬殺了提克迪奧斯，將這件遺物據為己有。之後他並沒有交出它。他對魔法的渴望終究勝過了謹慎，而因為動用了燃燒軍團自身的力量，他被自己的哥哥瑪法里恩放逐。",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "安戈洛環形山",
		short = "安戈洛環形山被三片沙漠隔絕於其間，是一道深陷於卡林多南方的綠色傷口，在這裡，世界忘記了荒蕪。",
		full = "安戈洛環形山被三片沙漠隔絕於其間，是一道深陷於卡林多南方的綠色傷口，在這裡，世界忘記了荒蕪。比記憶更古老的恐龍在叢林中穿行，有些長到了任何活物都不該有的體長；大地與火焰的元素生物在牠們之間從容行走。在上方的山脊上，矗立著一座座從未有人解釋過的晶塔。\n\n流沙之戰期間，夜精靈被迫穿越這座環形山，一路退到塔納利斯沙漠的邊緣，而其拉的攻勢也在那裡瓦解。安戈洛本身有某種力量不容入侵者奪取這片土地，儘管沒有人說得清那究竟是什麼。\n\n一支由威利德與霍蘭妮·馬紹爾率領的遠征隊曾試圖在此建立據點，但環形山的兇險遠超出他們的準備。他們的營地被攻破，倖存者逃往高處，在如今被稱為馬紹爾營地的地方堅守不退。",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "月光林地",
		short = "月光林地安臥於環繞的群山之中，是一座隱秘的山谷，這裡的森林從未遭受過腐化。",
		full = "月光林地安臥於環繞的群山之中，是一座隱秘的山谷，這裡的森林從未遭受過腐化。谷地中心是以女神之名命名的月神湖，湖畔的永夜港裡，牛頭人與夜精靈和睦共處，彼此對自然懷著同樣的崇敬，而月光林地守衛絕不容許這份和諧遭到破壞。\n\n先祖之戰的年代，當夜精靈在燃燒軍團面前瀕臨覆滅之際，瑪法里恩·怒風正是來到了這座山谷。瑪法里恩深知他的族人無法獨自取勝，於是帶著泰蘭妲·語風與他的弟弟伊利丹進入月光林地神聖的寂靜之中，懇求塞納留斯伸出援手。半神回應了他們，而在大崩裂重塑世界之後，曾在此避難的林地守護者與樹妖便走入了這個新的世界。塞納留斯本人從未離開，月光林地也成為德魯伊信仰最神聖的土地。\n\n在無數的土丘之下，沉睡著歷代德魯伊的聖所；而在月神湖的湖水之下，沉睡著曾受伊露恩寵愛的半神年獸，睡得並不安穩。",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "希利蘇斯",
		short = "這片沙漠位於卡林多遙遠的西南邊緣，是一片碎石與黃沙的荒原，可經由安戈洛環形山延伸而出的寬闊道路抵達。",
		full = "這片沙漠位於卡林多遙遠的西南邊緣，是一片碎石與黃沙的荒原，可經由安戈洛環形山延伸而出的寬闊道路抵達。在它的地表之下，是阿基爾帝國的殘餘──安其拉，夜精靈封印了它的中央神殿，試圖阻止某種可怕的存在甦醒。然而散落在希利蘇斯各處的遺跡，以及如今在沙地中遍布的異種蠍巢穴，都足以證明封印並未守住。\n\n很久以前，其拉人自己被驅趕到甲蟲之牆之後，在流沙之戰結束後被囚禁在那裡。但他們的僕從異種蠍卻被留在外頭，數百年來不斷繁衍，擴散到整個卡林多南部，直到夜精靈判斷這個威脅已大到無法再坐視不管，於是轉而重新開啟安其拉之門，以完成那道牆只能拖延的使命。\n\n塞納里奧議會在塞納里奧城堡保持警戒，追蹤異種蠍的蟲群，並評估牠們是否已成為任何單一民族都無法獨力面對的危險。",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "冬泉谷",
		short = "冬泉谷的積雪綿延無際，即使南部已被惡魔佔據，它的美麗依舊未受侵擾。這裡曾是許多藍龍軍團成員的家園，其中包括瑪里苟斯的伴侶哈雷。",
		full = "冬泉谷的積雪綿延無際，即使南部已被惡魔佔據，它的美麗依舊未受侵擾。這裡曾是許多藍龍軍團成員的家園，其中包括瑪里苟斯的伴侶哈雷。\n\n一萬年前，精靈貴族從埃達拉斯的一座神殿竊取了辛瑪洛水晶，並在此建立了凱斯利爾城。他們無法抗拒試探水晶力量的誘惑，而當水晶碎裂時，它釋放出的詛咒吞噬了他們。大崩裂完成了水晶所開始的毀滅，凱斯利爾淪為廢墟。城中的亡者從未離去。後來，高等精靈從奎爾薩拉斯前來尋找水晶的碎片，同樣的瘋狂也攫住了他們。如今，他們的鬼魂與他們前來研究的那些亡魂一同在廢墟中徘徊。\n\n哥布林佔據著山谷中心的永望鎮，而夜精靈至今仍在這裡守望，守護著一片比他們雙方都更加古老的家園。",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "暴風城",
		short = "在獸人部落將暴風城焚毀之後，它在年輕的瓦里安國王治下，由石匠公會以白石重建而起。",
		full = "在獸人部落將暴風城焚毀之後，它在年輕的瓦里安國王治下，由石匠公會以白石重建而起。然而當王室的國庫因戰爭債務而枯竭，貴族們拒絕支付公會工資時，會長艾德溫·范克里夫的抗議換來的卻是公會的解散。暴動隨之而起，蒂芬·烏瑞恩王后在混亂中喪命。瓦里安的怒火將石匠們放逐到西部荒野，他們在那裡成了迪菲亞兄弟會──而在王座背後，一位名叫卡特拉娜·普瑞斯托的顧問，為了自己的目的，悄悄地讓國王與公會反目成仇。\n\n此後瓦里安國王在可疑的情況下失蹤，在普瑞斯托女伯爵的力勸之下，王冠交給了他年幼的兒子安度因王子，以維持王國的秩序。伯瓦爾·弗塔根公爵擔任暴風城的攝政王與軍隊統帥，而普瑞斯托女伯爵則在如何運用王國資源一事上為他出謀劃策，在城堡之中既無人懷疑，也無人挑戰。",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "奧格瑪",
		short = "奧格瑪興起於海加爾山之役後的歲月，當時大酋長索爾帶領他的族人來到卡林多一片荒涼的海岸。",
		full = "奧格瑪興起於海加爾山之役後的歲月，當時大酋長索爾帶領他的族人來到卡林多一片荒涼的海岸。他以父親之名將這片土地命名為杜洛塔，並以塑造了他的摯友與導師奧格林·末日錘之名，將他在此建立的城市命名為奧格瑪。這座城市建得很快，卻絕不草率：堅固的城牆、巨大的城門、高聳的塔樓，背後的山脈也被鑿刻成要塞的一部分，讓大地本身守護著這座城市。\n\n建造它的部落，已不是昔日在世界各地燃起戰火的那個部落。惡魔的詛咒被打破之後，索爾的族人從征服轉向生存，而奧格瑪的建造不只仰賴獸人──哥布林、牛頭人與暗矛食人妖都與他們並肩勞動，莫克納薩爾族的雷克薩也曾出手相助。半人馬、鷹身人、雷霆蜥蜴、狗頭人與野豬人都曾在這座年輕城市最初的歲月裡考驗過它，但它屹立不搖，不僅成為獸人的家園，也成為食人妖、牛頭人，以及後來新近被接納加入部落的被遺忘者的家園。\n\n在這裡，就連風也不是朋友：如刀鋒般的狂風橫掃山谷，力道之強，足以掀掉任何建造不夠用心的屋頂。",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "鐵爐堡",
		short = "鐵爐堡是矮人的首都，開鑿於丹莫洛北部鐵爐山的深處，是矮人的祖居之地，也是艾澤拉斯最古老的城市之一。",
		full = "鐵爐堡是矮人的首都，開鑿於丹莫洛北部鐵爐山的深處，是矮人的祖居之地，也是艾澤拉斯最古老的城市之一。它是卡茲莫丹的首都，由銅鬚氏族的國王麥格尼·銅鬚統治。\n\n鐵爐堡是一座廣闊的地下城市，住滿了工匠、探險家、礦工與戰士，以工業聞名，也是聯盟的商業中心；它既是要塞，也是首都，見證了矮人的力量與堅韌。這座城市由一圈圈同心環構成，越往地底深處樓層越小，全都以城市中心那座與城市同名的大熔爐為中心向外輻射。城中遍布狹窄的通道、開鑿在岩壁中的店鋪，以及宛如洞窟的廳室。這裡的氛圍熙來攘往、喧鬧而充滿工業氣息，卻又溫馨舒適；旅店與商店的壁爐中火焰熊熊，處處可以聽見矮人的笑聲與嬉鬧。與暴風城和達納蘇斯不同，這座城市是矮人親手在大地中開鑿出的巨大洞窟，天花板與地面都是堅硬的岩石。",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "雷霆崖",
		short = "雷霆崖矗立在莫高雷草原上方四座狂風吹拂的高地上，只能搭乘牛頭人以繩索與木材製成的升降梯，或經由高地之間懸掛的長橋抵達。",
		full = "雷霆崖矗立在莫高雷草原上方四座狂風吹拂的高地上，只能搭乘牛頭人以繩索與木材製成的升降梯，或經由高地之間懸掛的長橋抵達。每座高地的頂端都布滿了帳篷、長屋與彩繪的圖騰。世世代代以來，牛頭人一直過著游牧生活，不斷受到在卡林多各地橫行的半人馬侵擾。終結這段流亡的是血蹄部族的酋長凱恩·血蹄。第三次大戰期間，大酋長索爾與他的新部落來到莫高雷，他們的力量與凱恩的力量合而為一，共同擊潰了半人馬，終於為牛頭人贏得了這片草原。凱恩在高地上建立了一座向所有流散部族敞開的避難所，久而久之，這些部族團結在他的領導之下，成為一個民族；他們對未來的道路有時意見分歧，卻從未懷疑他領導他們的智慧。\n\n這些崖壁至今仍在高地與橋梁之間、在聚集於同一位酋長麾下的各部族帳篷之中，承載著那段建城歷史的份量。",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "達納蘇斯",
		short = "夜精靈在第三次大戰之後建立了達納蘇斯，那時他們漫長的永生已然消逝。許多人無法承受突然降臨的衰老與脆弱。",
		full = "夜精靈在第三次大戰之後建立了達納蘇斯，那時他們漫長的永生已然消逝。許多人無法承受突然降臨的衰老與脆弱。一些悲痛的德魯伊決心種下一棵新的世界之樹，以恢復他們與永恆世界的連結。由於瑪法里恩·怒風下落不明，范達爾·鹿盔接下了大德魯伊的重任，領導這項工作。他們培育的這棵巨樹──泰達希爾，自海岸外拔地而起，直到樹冠衝破雲層；夜精靈在它的枝幹間建立了他們的城市，作為族人倖存的見證。\n\n與人類和矮人那些封閉、築有城牆的城市不同，達納蘇斯向天空敞開。城市環繞著一座寬闊的湖泊而建，湖岸以優雅的橋梁相連，小徑上鋪滿了落葉。月神殿高聳於樹林之上，是大祭司泰蘭妲·語風與伊露恩姐妹會的所在，旁邊是哨兵駐守的列柱正義之廳。這座城市依然是它當初被建造時的模樣：一處寧靜的避難所，也是一座紀念碑，紀念一個正在學習與死亡共處的民族。",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "幽暗城",
		short = "早在被遺忘者將其據為己有之前，幽暗城便已有它的名字與用途。在羅德隆王宮的深處，延伸著王室亡者的古老墓穴、地牢與下水道。",
		full = "早在被遺忘者將其據為己有之前，幽暗城便已有它的名字與用途。在羅德隆王宮的深處，延伸著王室亡者的古老墓穴、地牢與下水道。這裡原本只用來關押囚犯與安置屍體，但羅德隆最貧窮的人們還是擠進了這片黑暗之中，而衛兵們的清掃行動始終無法將他們趕盡。\n\n當巫妖王對其造物的掌控出現鬆動時，希瓦娜斯·風行者帶著那些保有神智的亡靈脫離了天譴軍團，轉而對付阿薩斯──那位將她變成如今模樣的墮落王子。她將他引入這個殘破王國中的陷阱；他在科爾蘇加德的幫助下逃脫，逃往北方，自己成為了巫妖王。希瓦娜斯與她的追隨者成了這片戰場的主人，自稱為被遺忘者，並佔據了這座殘破首都地下的墓穴，完成了天譴軍團起了頭的要塞。\n\n如今矗立在此的是一座為防禦而建的迷宮：有毒的污泥河流貫穿每一條大道，空氣中瀰漫著生者幾乎無法忍受呼吸的濃烈煙霧。對被遺忘者而言，這裡是在一個仍在獵殺他們的世界中的避風港。",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
}

